mapper.select:
select *
from message
where messageSender = #{messageSender}
   or messageReciver = #{messageSender}
order by messageDate asc

mapper.update:
update message set messageRead=1,messagereader=#{messageReciver} where messageRead=0

    and messageSender=#{messageSender}


    and messageReciver=#{messageReciver}

mapper.select:
select count(messageId) count
from message
where messageReciver=#{messageReciver}
  and messageSender=#{messageSender}
  and isnull(messageRead,'0')='0'
